"""Cron-style schedules. SCHEDULE.md has the full rules."""

import calendar
import re
from datetime import date, datetime, timedelta

_MONTH_NAMES = {
    "jan": 1,
    "feb": 2,
    "mar": 3,
    "apr": 4,
    "may": 5,
    "jun": 6,
    "jul": 7,
    "aug": 8,
    "sep": 9,
    "oct": 10,
    "nov": 11,
    "dec": 12,
}

_DAY_NAMES = {
    "sun": 0,
    "mon": 1,
    "tue": 2,
    "wed": 3,
    "thu": 4,
    "fri": 5,
    "sat": 6,
}

_SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}

_BOUNDS = {
    "minute": (0, 59),
    "hour": (0, 23),
    "dom": (1, 31),
    "month": (1, 12),
    "dow": (0, 7),
}

_NUMBER = re.compile(r"[0-9]+\Z")


def _is_number(text):
    return bool(_NUMBER.fullmatch(text))


def _value(token, kind, allow_names):
    low, high = _BOUNDS[kind]
    if _is_number(token):
        value = int(token)
        if not low <= value <= high:
            raise ValueError(f"value out of range: {token!r}")
        return value
    if allow_names and len(token) == 3:
        table = _MONTH_NAMES if kind == "month" else _DAY_NAMES if kind == "dow" else None
        if table is not None:
            name = token.lower()
            if name in table:
                return table[name]
    raise ValueError(f"bad value: {token!r}")


def _expand_range(start, end, kind):
    low, high = _BOUNDS[kind]
    if kind == "dow":
        if start <= end:
            return list(range(start, end + 1))
        if start == 7:
            start = 0
        if start <= end:
            return list(range(start, end + 1))
        return list(range(start, 7)) + list(range(0, end + 1))
    if start <= end:
        return list(range(start, end + 1))
    return list(range(start, high + 1)) + list(range(low, end + 1))


def _parse_field(text, kind):
    low, high = _BOUNDS[kind]
    fixed = set()
    last_day = False
    last_weekdays = set()
    nth_weekdays = set()

    if text == "?":
        if kind not in ("dom", "dow"):
            raise ValueError("'?' is only allowed for day fields")
        text = "*"

    for item in text.split(","):
        if not item:
            raise ValueError("empty item")

        if kind == "dom" and item == "L":
            last_day = True
            continue

        if kind == "dow":
            match = re.fullmatch(r"([0-9]+)L", item)
            if match:
                n = int(match.group(1))
                if not 0 <= n <= 7:
                    raise ValueError(f"value out of range: {n!r}")
                last_weekdays.add(0 if n == 7 else n)
                continue
            match = re.fullmatch(r"([0-9]+)#([0-9]+)", item)
            if match:
                n = int(match.group(1))
                k = int(match.group(2))
                if not 0 <= n <= 7:
                    raise ValueError(f"value out of range: {n!r}")
                if not 1 <= k <= 5:
                    raise ValueError(f"value out of range: {k!r}")
                nth_weekdays.add((0 if n == 7 else n, k))
                continue

        if kind in ("dom", "dow") and ("L" in item or "#" in item):
            raise ValueError(f"bad item: {item!r}")
        if kind in ("minute", "hour", "month") and "#" in item:
            raise ValueError(f"bad item: {item!r}")

        pieces = item.split("/")
        if len(pieces) > 2:
            raise ValueError(f"bad item: {item!r}")
        base = pieces[0]
        step = None
        if len(pieces) == 2:
            step_text = pieces[1]
            if not _is_number(step_text):
                raise ValueError(f"bad step: {step_text!r}")
            step = int(step_text)
            if step < 1:
                raise ValueError("step must be at least 1")

        allow_names = kind in ("month", "dow") and step is None

        if base == "*":
            values = list(range(low, high + 1))
        elif "-" in base:
            ends = base.split("-")
            if len(ends) != 2 or not ends[0] or not ends[1]:
                raise ValueError(f"bad range: {base!r}")
            start = _value(ends[0], kind, allow_names)
            end = _value(ends[1], kind, allow_names)
            values = _expand_range(start, end, kind)
        else:
            if not base:
                raise ValueError("empty item")
            value = _value(base, kind, allow_names)
            values = list(range(value, high + 1)) if step is not None else [value]

        if step is not None:
            values = values[::step]

        for value in values:
            if kind == "dow" and value == 7:
                value = 0
            fixed.add(value)

    return {
        "fixed": fixed,
        "last_day": last_day,
        "last_weekdays": last_weekdays,
        "nth_weekdays": nth_weekdays,
    }


def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("schedule expression must be text")
    text = expr.strip()
    lowered = text.lower()

    if lowered.startswith("@"):
        if lowered not in _SHORTCUTS:
            raise ValueError(f"unknown shortcut: {expr!r}")
        text = _SHORTCUTS[lowered]

    fields = re.split(r"[ \t]+", text)
    if len(fields) != 5:
        raise ValueError(f"schedule needs five fields: {expr!r}")

    minute = _parse_field(fields[0], "minute")
    hour = _parse_field(fields[1], "hour")
    day_of_month = _parse_field(fields[2], "dom")
    month = _parse_field(fields[3], "month")
    day_of_week = _parse_field(fields[4], "dow")

    return {
        "minutes": sorted(minute["fixed"]),
        "minute_set": minute["fixed"],
        "hours": sorted(hour["fixed"]),
        "hour_set": hour["fixed"],
        "months": month["fixed"],
        "dom": day_of_month,
        "dow": day_of_week,
    }


def _last_day_of_month(when):
    return calendar.monthrange(when.year, when.month)[1]


def _day_matches(schedule, when):
    if when.month not in schedule["months"]:
        return False

    dom = schedule["dom"]
    if dom["last_day"] and when.day == _last_day_of_month(when):
        dom_ok = True
    else:
        dom_ok = when.day in dom["fixed"]
    if not dom_ok:
        return False

    dow = schedule["dow"]
    weekday = (when.weekday() + 1) % 7
    if weekday in dow["fixed"]:
        return True
    if weekday in dow["last_weekdays"]:
        return True
    occurrence = (when.day - 1) // 7 + 1
    return (weekday, occurrence) in dow["nth_weekdays"]


def matches(expr, when):
    """True if the schedule expr runs at the minute of the datetime when."""
    schedule = _parse(expr)
    return (
        when.month in schedule["months"]
        and when.hour in schedule["hour_set"]
        and when.minute in schedule["minute_set"]
        and _day_matches(schedule, when)
    )


def next_run(expr, after):
    """The first run of expr strictly after the datetime after, or None."""
    schedule = _parse(expr)

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
        limit = after + timedelta(days=20 * 365)
    except (OverflowError, ValueError):
        return None

    if start > limit:
        return None

    current = start.date()
    last_date = limit.date()
    start_date = start.date()
    hours = schedule["hours"]
    minutes = schedule["minutes"]

    while current <= last_date:
        if current.month not in schedule["months"]:
            if current.month == 12:
                if current.year == 9999:
                    return None
                current = date(current.year + 1, 1, 1)
            else:
                current = date(current.year, current.month + 1, 1)
            continue

        if _day_matches(schedule, current):
            first_hour = start.hour if current == start_date else 0
            first_minute = start.minute if current == start_date else 0
            found = None
            for hour in hours:
                if hour < first_hour:
                    continue
                if hour == first_hour:
                    for minute in minutes:
                        if minute >= first_minute:
                            found = (hour, minute)
                            break
                else:
                    found = (hour, minutes[0])
                if found is not None:
                    break

            if found is not None:
                candidate = datetime(
                    current.year, current.month, current.day, found[0], found[1]
                )
                if candidate > limit:
                    return None
                return candidate

        try:
            current += timedelta(days=1)
        except OverflowError:
            return None

    return None

