def _parse(expr):
    if not isinstance(expr, str):
        raise ValueError("schedule expression must be text")
    text = expr.strip()
    lowered = text.lower()

    if lowered.startswith("@"):
        if lowered not in _SHORTCUTS:
            raise ValueError(f"unknown shortcut: {expr!r}")
        text = _SHORTCUTS[lowered]

    fields = re.split(r"[ \t]+", text)
    if len(fields) != 5:
        raise ValueError(f"schedule needs five fields: {expr!r}")

    minute = _parse_field(fields[0], "minute")
    hour = _parse_field(fields[1], "hour")
    day_of_month = _parse_field(fields[2], "dom")
    month = _parse_field(fields[3], "month")
