        "minute_set": minute["fixed"],
        "hours": sorted(hour["fixed"]),
        "hour_set": hour["fixed"],
        "months": month["fixed"],
        "dom": day_of_month,
        "dow": day_of_week,
    }


def _last_day_of_month(when):
    return calendar.monthrange(when.year, when.month)[1]


def _day_matches(schedule, when):
    if when.month not in schedule["months"]:
        return False

    dom = schedule["dom"]
    if dom["last_day"] and when.day == _last_day_of_month(when):
        dom_ok = True
    else:
        dom_ok = when.day in dom["fixed"]
    if not dom_ok:
        return False

    dow = schedule["dow"]
    weekday = (when.weekday() + 1) % 7
